import json,shutil
from pathlib import Path
root=Path(__file__).resolve().parents[2];dest=root/'Docs/Foundation/Phase4Evidence';dest.mkdir(parents=True,exist_ok=True)
def read(name):
    data=json.loads((root/'Saved/Phase4'/name).read_text());return data,{r['name']:r for r in data['samples']}
raw_e,e=read('equipment_results.json');raw_b,b=read('ballistics_results.json');raw_t,t=read('throwable_results.json')
checks=[]
def check(name,value):checks.append({'check':name,'passed':bool(value)})
def delta(rows,a,z,field='shots'):return rows[z][field]-rows[a][field]
check('initial existing firearm and ammunition',e['initial']['ammo']==30 and e['initial']['reserve']==90 and len(e['initial']['slots'])==1)
check('semi hold fires once',delta(e,'initial','semi_hold')==1 and e['semi_hold']['ammo']==29)
check('second trigger fires once',delta(e,'semi_release','second_semi')==1)
check('reload blocks firing',e['reload_fire_rejected']['reload'] and delta(e,'reload_start','reload_fire_rejected')==0)
check('reload conserves magazine and reserve',e['reload_complete']['ammo']==30 and e['reload_complete']['reserve']==88)
check('full reload rejected',e['full_reload_rejected']['ammo']==30 and e['full_reload_rejected']['reserve']==88 and not e['full_reload_rejected']['reload'])
check('zero reserve rejects reload',e['no_reserve_reload_rejected']['ammo']==27 and e['no_reserve_reload_rejected']['reserve']==0 and not e['no_reserve_reload_rejected']['reload'])
check('limited reserve transfers minimum',e['limited_reload']['ammo']==7 and e['limited_reload']['reserve']==0)
check('dry click consumes no ammunition and fires no shot',e['dry_click']['ammo']==0 and delta(e,'empty_arrange','dry_click')==0 and e['dry_click']['dry']>e['empty_arrange']['dry'])
check('automatic hold fires repeatedly within rate',4<=delta(e,'auto_mode','auto_hold')<=7)
check('automatic release stops firing after input is processed',delta(e,'auto_release_applied','auto_release')==0)
check('burst completes exactly three shots after short press',delta(e,'burst_mode','burst_release')==3)
check('rapid triggers respect cooldown',1<=delta(e,'rapid_initial','rapid_complete')<6)
check('ADS narrows FOV and spread',e['ads_hold']['ads']>.98 and abs(e['ads_hold']['fov']-65)<.1 and e['ads_hold']['spread']<e['initial']['spread'])
check('ADS hides existing crosshair', 'HIDDEN' in e['ads_hold']['crosshair'])
check('ADS release restores FOV and crosshair',abs(e['ads_release']['fov']-90)<.1 and 'HIDDEN' not in e['ads_release']['crosshair'])
metrics=e['ads_look_end']['look_metrics']
ratio=(metrics['ads_delta']/metrics['ads_frames'])/(metrics['hip_delta']/metrics['hip_frames']) if metrics.get('hip_delta') else 0
check('actual look input scales to sixty percent in ADS',.5<ratio<.7)
check('pickup creates second unique slot',len(e['pickup_release']['slots'])==2 and len({s['id'] for s in e['pickup_release']['slots']})==2)
check('alternate inherits weapon and starts with its capacity',e['switch_alt']['weapon_class']=='BP_Weapon_AlternateTest_C' and e['switch_alt']['ammo']==20 and e['switch_alt']['reserve']==60)
check('switch preserves base ammunition',e['switch_base']['ammo']==12 and e['switch_base']['reserve']==34)
check('switch preserves alternate ammunition',e['alt_again']['ammo']==20 and e['alt_again']['reserve']==60)
check('drop removes one inventory copy',len(e['drop_alt']['slots'])==1 and e['drop_alt']['ammo']==12)
check('reclaim preserves dropped magazine and reserve',len(e['reclaimed_alt']['slots'])==2 and e['reclaimed_alt']['ammo']==20 and e['reclaimed_alt']['reserve']==60)
check('holster blocks firing',e['holster_fire_rejected']['holstered'] and delta(e,'holster','holster_fire_rejected')==0)
check('inspection blocks firing',e['inspect_fire_rejected']['inspect'] and delta(e,'inspect_begin','inspect_fire_rejected')==0)
check('alternate actually fires and reloads with its own capacity',e['alternate_fire']['ammo']==19 and e['alternate_reload']['ammo']==20 and e['alternate_reload']['reserve']==59)
check('dropping both firearms leaves an empty loadout',len(e['drop_all_base']['slots'])==0 and e['drop_all_base']['weapon_class'] is None)
check('unarmed ADS is rejected',e['unarmed_ads_rejected']['ads']<.01 and abs(e['unarmed_ads_rejected']['fov']-90)<.1)
check('pickup restores equipment from an empty loadout',len(e['base_recovered']['slots'])==1 and e['base_recovered']['ammo']==12 and e['base_recovered']['reserve']==34)
check('normal cover blocks hitscan',b['pen_disabled']['P4_PenetrationTarget']==100)
check('tagged thin cover passes reduced damage',b['pen_thin']['penetrated'] and b['pen_thin']['P4_PenetrationTarget']==90)
check('thick cover rejects penetration',not b['pen_thick_rejected']['penetrated'] and b['pen_thick_rejected']['P4_PenetrationTarget']==90)
check('untagged cover rejects penetration',not b['pen_untagged_rejected']['penetrated'] and b['pen_untagged_rejected']['P4_PenetrationTarget']==90)
check('projectile collision applies actual damage',b['projectile_hit']['projectile_impacts']==1 and b['projectile_hit']['P4_ProjectileTarget']<100)
check('head multiplier applies forty damage',abs(b['head_hit']['damage']-40)<.1 and b['head_hit']['P4_LimbTarget']==60)
check('limb multiplier applies thirteen damage',abs(b['limb_hit']['damage']-13)<.1 and b['limb_hit']['P4_LimbTarget']==47)
check('distance falloff reduces damage',0<b['range_hit']['damage']<40 and abs(100-b['range_hit']['P4_RangeTarget']-b['range_hit']['damage'])<.1)
check('bounded physical shell ejection',b['range_hit']['shells']==b['range_hit']['shots'] and b['range_hit']['shells']>0)
check('stone preparation spends a finite item and draws trajectory',t['stone_hold']['inventory']['stone']==4 and t['stone_preview']['visible_preview']>0 and t['stone_hold']['held'])
stone=next(a for a in t['stone_impacts']['throwables'] if 'STONE' in a['kind'])
check('stone actually simulates physics and emits bounded impact events',stone['physics'] and stone['launched'] and 0<stone['events']<10)
check('released trajectory disappears',t['stone_launch']['visible_preview']==0)
check('stone can be retrieved once',t['stone_retrieved']['inventory']['stone']==5 and not any('STONE' in a['kind'] for a in t['stone_retrieved']['throwables']))
knife=next(a for a in t['knife_embed']['throwables'] if 'KNIFE' in a['kind'])
check('knife embeds and leaves finite inventory',knife['impacted'] and not knife['physics'] and t['knife_embed']['inventory']['knife']==2)
check('knife retrieval removes world copy and restores one item',t['knife_retrieved']['inventory']['knife']==3 and not any('KNIFE' in a['kind'] for a in t['knife_retrieved']['throwables']))
check('world grenade pickups grant once',t['P4_GrenadePickup_release']['inventory']['frag']==3 and t['P4_CookGrenadePickup_release']['inventory']['frag']==4)
check('frag harms target after real fuse',t['frag_hold']['P4_BlastTarget']==100 and t['frag_damage']['P4_BlastTarget']==0)
check('wall blocks radial damage',t['shielded_damage']['P4_ShieldedTarget']==100)
check('removing same wall permits radial damage',t['unshielded_damage']['P4_ShieldedTarget']==0)
check('smoke activates after fuse',any('SMOKE' in a['kind'] and a['detonated'] for a in t['smoke_active']['throwables']))
check('held flash actually affects view and fades',t['flash_cook']['flash']>.5 and t['flash_fades']['flash']<.05)
check('cooking frag in hand kills owner and spends last item',t['cook_detonates']['health']==0 and t['cook_detonates']['inventory']['frag']==0 and t['cook_detonates']['dead'])
report={'passed':sum(c['passed'] for c in checks),'total':len(checks),'checks':checks,'ads_sensitivity_ratio':ratio,'owner_approved':False,
 'limits':['Generated input, not owner hardware acceptance.','Procedural equipment/hand poses and original placeholder cues require visual/audio review.','Stone hearing must still be exercised against phase-5 AI.','Knives against live NPCs and final death/restart regression remain separate checks.']}
(dest/'checks.json').write_text(json.dumps(report,indent=2))
for filename in ('equipment_results.json','ballistics_results.json','throwable_results.json','ads.png','alternate.png','stone_preview.png','smoke.png','flash.png'):
    p=root/'Saved/Phase4'/filename
    if p.exists():shutil.copy2(p,dest/filename)
print(json.dumps(report,indent=2))
if report['passed']!=report['total']:raise SystemExit(1)
